/* Reuse video bytes and real frame thumbnails without restarting active players. */
(function(){
 'use strict';
 if(!window.StudioMediaCache)return;
 const cache=StudioMediaCache.createCache(),urls=new Map(),posters=new Map(),pending=new Map(),players=new WeakSet(),posterPending=new Map(),sidebarJobs=new Set();
 let owner='',generation=0,queue=[],running=0;
 const currentOwner=()=>cloudUser?String(cloudConfig.apiBase||location.origin)+'|'+String(cloudUser.id):'';
 const resourceKey=(r,kind='file')=>cache.key(owner,kind,r);
 function reset(){generation++;for(const url of urls.values())URL.revokeObjectURL(url);urls.clear();posters.clear();pending.clear();posterPending.clear();sidebarJobs.clear();queue=[];owner=currentOwner();}
 function ensureOwner(){if(owner!==currentOwner())reset();return owner;}
 function objectURL(key,blob){if(!urls.has(key))urls.set(key,URL.createObjectURL(blob));return urls.get(key);}
 function enqueue(action){queue.push(action);drain();}
 function drain(){while(running<2&&queue.length){const action=queue.shift();running++;Promise.resolve().then(action).catch(()=>{}).finally(()=>{running--;drain();});}}
 function find(id){return state.records.find(r=>String(r.id)===String(id)&&!r.deleted);}
 async function bytes(r){const user=ensureOwner(),epoch=generation;if(!user)throw Error('请先登录');const key=resourceKey(r);if(pending.has(key))return pending.get(key);const work=cache.load(user,'file',r,async()=>{const response=await fetch((cloudConfig.apiBase||'')+r.contentPath,{headers:{'tenant-id':'1',Authorization:'Bearer '+cloudTokens.accessToken},credentials:'same-origin',cache:'default'});if(!response.ok)throw Error('素材读取失败，请刷新登录后重试');const blob=await response.blob();if(blob.type.includes('application/json'))throw Error('素材暂不可用');if(epoch!==generation||user!==currentOwner())throw Error('账号已切换');return blob;});pending.set(key,work);try{return await work;}finally{if(pending.get(key)===work)pending.delete(key);}}
 function updateThumbs(r,url){r.posterSrc=url;for(const session of state.sessions){const latest=state.records.find(item=>item.session===session.id&&!item.deleted);if(String(latest?.id)!==String(r.id))continue;for(const slot of document.querySelectorAll('[data-session-thumbnail]'))if(slot.dataset.sessionThumbnail===String(session.id)){const img=document.createElement('img');img.alt='';img.src=url;slot.replaceChildren(img);}}for(const v of document.querySelectorAll('video[data-record-media]'))if(v.dataset.recordMedia===String(r.id))v.poster=url;}
 async function restorePoster(r){const user=ensureOwner(),epoch=generation;if(!user)return false;const key=resourceKey(r,'poster-v3');if(posters.has(key)){updateThumbs(r,posters.get(key));return true;}const blob=await cache.get(user,'poster-v3',r);if(!blob||epoch!==generation||user!==currentOwner())return false;const url=objectURL(key,blob);posters.set(key,url);updateThumbs(r,url);return true;}
 async function capture(r,video){const user=ensureOwner(),epoch=generation;if(!user||video.readyState<2||!video.videoWidth)return;const key=resourceKey(r,'poster-v3');if(posters.has(key)||posterPending.has(key))return;const work=(async()=>{try{const canvas=document.createElement('canvas');canvas.width=Math.min(640,video.videoWidth);canvas.height=Math.max(1,Math.round(canvas.width*video.videoHeight/video.videoWidth));if(canvas.height>640){canvas.width=Math.max(1,Math.round(640*video.videoWidth/video.videoHeight));canvas.height=640;}canvas.getContext('2d').drawImage(video,0,0,canvas.width,canvas.height);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/webp',.78));if(!blob||epoch!==generation||user!==currentOwner())return;await cache.put(user,'poster-v3',r,blob);if(epoch!==generation)return;const url=objectURL(key,blob);posters.set(key,url);updateThumbs(r,url);}catch{}})();posterPending.set(key,work);try{await work;}finally{if(posterPending.get(key)===work)posterPending.delete(key);}}
 async function extractPoster(r,blob){const user=ensureOwner(),epoch=generation,key=resourceKey(r,'poster-v3');if(!user||posters.has(key)||sidebarJobs.has(key))return;sidebarJobs.add(key);try{if(await restorePoster(r)||epoch!==generation)return;await new Promise(resolve=>{const video=document.createElement('video');video.preload='metadata';video.muted=true;video.playsInline=true;let finished=false;const local=blob?URL.createObjectURL(blob):null;const done=()=>{if(finished)return;finished=true;clearTimeout(timer);video.onloadedmetadata=video.onseeked=video.onerror=null;video.removeAttribute('src');video.load();if(local)URL.revokeObjectURL(local);resolve();};const timer=setTimeout(done,12000);video.onloadedmetadata=()=>{video.currentTime=Math.min(.12,Number.isFinite(video.duration)?video.duration/2:.12);};video.onseeked=async()=>{if(epoch===generation)await capture(r,video);done();};video.onerror=done;video.src=local||(cloudConfig.apiBase||'')+r.contentPath;});}finally{sidebarJobs.delete(key);}}
 async function prepare(video){const user=ensureOwner(),r=find(video.dataset.recordMedia),epoch=generation;if(!user||!r||!video.isConnected)return;try{const blob=await cache.get(user,'file',r);if(epoch!==generation||!video.isConnected||user!==currentOwner())return;if(!video.getAttribute('src'))video.src=blob?objectURL(resourceKey(r),blob):(cloudConfig.apiBase||'')+r.contentPath;await restorePoster(r);if(blob)enqueue(()=>extractPoster(r,blob));else if(Number(r.byteSize)>0&&r.byteSize<=cache.maxFileBytes)enqueue(async()=>{if(epoch===generation&&user===currentOwner()){const saved=await bytes(r);if(epoch===generation)await extractPoster(r,saved);}});else enqueue(()=>{if(epoch===generation)return extractPoster(r);});}catch{if(epoch===generation&&video.isConnected&&!video.getAttribute('src'))video.src=(cloudConfig.apiBase||'')+r.contentPath;}}
 const visible=window.IntersectionObserver?new IntersectionObserver(entries=>{for(const entry of entries)if(entry.isIntersecting){visible.unobserve(entry.target);prepare(entry.target);}},{rootMargin:'160px'}):null;
 function scan(){ensureOwner();if(!owner)return;for(const video of document.querySelectorAll('video[data-record-media]'))if(!players.has(video)){players.add(video);if(visible)visible.observe(video);else prepare(video);}}
 async function sidebar(){const user=ensureOwner(),epoch=generation;if(!user)return;for(const session of state.sessions){const r=state.records.find(item=>item.session===session.id&&!item.deleted);if(r?.mode==='video'){if(await restorePoster(r))continue;if(epoch!==generation)return;/* Mounted players supply frames without a duplicate video request. */if([...document.querySelectorAll('video[data-record-media]')].some(v=>v.dataset.recordMedia===String(r.id)))continue;enqueue(async()=>{if(epoch===generation)await extractPoster(r);});}}}
 const previousSessions=renderSessions;renderSessions=function(search=''){previousSessions(search);sidebar().catch(()=>{});};
 const previousRelease=cloudRelease;cloudRelease=function(){previousRelease();reset();};
 window.StudioMedia={deferred:true,bytes,poster:r=>{ensureOwner();return posters.get(resourceKey(r,'poster-v3'))||r.posterSrc||'';},reset};
 document.addEventListener('timeupdate',event=>{const video=event.target;if(video.matches?.('video[data-record-media]')){const r=find(video.dataset.recordMedia);if(r&&video.currentTime>.08)capture(r,video);}},true);
 const observer=new MutationObserver(()=>{if(!scheduled){scheduled=true;queueMicrotask(()=>{scheduled=false;scan();});}});let scheduled=false;observer.observe(document.body,{childList:true,subtree:true});scan();
 document.addEventListener('error',event=>{const img=event.target;if(!img.matches?.('.session-thumb img'))return;const slot=img.parentElement;slot.innerHTML=icon('video');},true);
})();
